std::string get_enhanced_backtrace(int skip = 1);

std::string get_enhanced_backtrace(int skip)
{
    json backtrace = get_backtrace(skip);
    std::string enhanced_backtrace;
    for (const auto& entry : backtrace)
    {
        enhanced_backtrace += entry["function"].get<std::string>() + "\n";
    }
    return enhanced_backtrace;
}

