          buf_t chunk("custom pool buffer", pool_size);
          for (int i = 1; i < nbuf; ++i) {
            pool->AddFreeObjectToPool(
                buf_t(chunk, std::make_pair(i * buf_size, (i + 1) * buf_size)));
          }
          return buf_t(chunk, std::make_pair(0, buf_size));
