#include "force.h"

class ForceEAM : Force
{
  public:

    typedef eng_virial_type value_type;


    struct TagHalfNeighInitial {};
    template<int EVFLAG>
    struct TagHalfNeighMiddle {};
    template<int EVFLAG>
    struct TagHalfNeighFinal {};

