class string_ex : public std::string
{
public:

	int format(const char *fmt, ...)
	{
		va_list args;
		va_start(args, fmt);
		size_t len = std::vsnprintf(nullptr, 0, fmt, args);
		va_end(args);

		this->resize(len);

		va_start(args, fmt);
		std::vsnprintf((char*)c_str(), len+1, fmt, args);
		va_end(args);

		return 0;
	}
	void replace(char a, char b)
	{
		for (size_t i = 0; i < size(); i++)
			if (at(i) == a)
				(*this)[i] = b;
	}
};

