                jfieldID dexElementsFieldID = env->GetFieldID(dexPathListClass, "dexElements", "[Ldalvik/system/DexPathList$Element;");

                if (pathListFieldID == nullptr || dexElementsFieldID == nullptr) {
                    ENTRYLOGE("Failed to find fields");
