#include <dji_interface/dji_interface.h>

namespace dji_interface {

DJIInterface::DJIInterface(const ros::NodeHandle& nh, const ros::NodeHandle& private_nh)
    : nh_(nh), private_nh_(private_nh), initialized_(false), dji_comm_(nh, private_nh) {
  loadParameters();
  init();
  setPublishers();
  setSubscribers();
}

DJIInterface::~DJIInterface() {
}

void DJIInterface::loadParameters() {
  private_nh_.param<std::string>("frame_id", frame_id_, "base_link");
  private_nh_.param<std::string>("device", device_, "/dev/ttyUSB0");
  private_nh_.param<int>("baudrate", baudrate_, 230400);
  private_nh_.param<double>("thrust_coefficient", thrust_coefficient_, kDefaultThrustCoefficient);
  private_nh_.param<double>("minimum_thrust", minimum_thrust_, kDefaultMinimumThrust);
  private_nh_.param<double>("maximum_thrust", maximum_thrust_, kDefaultMaximumThrust);
  private_nh_.param<double>("thrust_offset", thrust_offset_, 0.0);
}

void DJIInterface::init() {
  dji_comm_.init(device_, baudrate_);
  dji_comm_.setBroadcastCallback(&DJIInterface::broadcastCallback, this);
  dji_comm_.activate(&activation_data_, NULL); #Modify
  initialized_ = true;
}

void DJIInterface::setPublishers() {
  imu_pub_ = nh_.advertise<sensor_msgs::Imu>("imu", 10);
  rc_pub_ = nh_.advertise<sensor_msgs::Joy>("rc_data", 10);
  status_pub_ = nh_.advertise<mav_msgs::Status>("status", 10);
  gps_pub_ = nh_.advertise<sensor_msgs::NavSatFix>("gps", 10);
}

void DJIInterface::setSubscribers() {
  command_roll_pitch_yawrate_thrust_sub_ = nh_.subscribe(
      mav_msgs::default_topics::COMMAND_ROLL_PITCH_YAWRATE_THRUST,
      10,
      &DJIInterface::commandRollPitchYawrateThrustCallback, this);
}

void DJIInterface::broadcastCallback() {
  DJI::onboardSDK::BroadcastData data;
  dji_comm_.getBroadcastData(&data);

  processIMU(data);
  processRc(data);
  processTimeStamp(data);
  processStatusInfo(data);
  processGPS(data);
}

void DJIInterface::processIMU(const DJI::onboardSDK::BroadcastData& data) {
  sensor_msgs::Imu imu_msg;
  imu_msg.header.stamp = ros::Time::now();
  imu_msg.header.frame_id = frame_id_;

  imu_msg.angular_velocity.x = data.v.angular_rate_y;
  imu_msg.angular_velocity.y = data.v.angular_rate_x;
  imu_msg.angular_velocity.z = data.v.angular_rate_z;

  imu_msg.linear_acceleration.x = data.v.acc_y;
  imu_msg.linear_acceleration.y = data.v.acc_x;
  imu_msg.linear_acceleration.z = data.v.acc_z;

  imu_pub_.publish(imu_msg);
}

void DJIInterface::processRc(const DJI::onboardSDK::BroadcastData& data) {
  sensor_msgs::Joy rc_msg;
  rc_msg.header.stamp = ros::Time::now();
  rc_msg.header.frame_id = frame_id_;

  rc_msg.axes.push_back(data.rc.roll / kRCStickMaxValue);
  rc_msg.axes.push_back(data.rc.pitch / kRCStickMaxValue);
  rc_msg.axes.push_back(data.rc.yaw / kRCStickMaxValue);
  rc_msg.axes.push_back(data.rc.throttle / kRCStickMaxValue);

  rc_pub_.publish(rc_msg);
}

void DJIInterface::processTimeStamp(const DJI::onboardSDK::BroadcastData& data) {
  // Process timestamp if needed
}

void DJIInterface::processStatusInfo(const DJI::onboardSDK::BroadcastData& data) {
  mav_msgs::Status status_msg;
  status_msg.header.stamp = ros::Time::now();
  status_msg.header.frame_id = frame_id_;

  status_msg.flight_status = data.status.flight;
  status_msg.mode = data.status.mode;
  status_msg.vrc_status = data.status.vrc;

  status_pub_.publish(status_msg);
}

void DJIInterface::processGPS(const DJI::onboardSDK::BroadcastData& data) {
  sensor_msgs::NavSatFix gps_msg;
  gps_msg.header.stamp = ros::Time::now();
  gps_msg.header.frame_id = frame_id_;

  gps_msg.latitude = data.pos.latitude * 180.0 / C_PI;
  gps_msg.longitude = data.pos.longitude * 180.0 / C_PI;
  gps_msg.altitude = data.pos.altitude;

  gps_pub_.publish(gps_msg);
}

void DJIInterface::commandRollPitchYawrateThrustCallback(const mav_msgs::RollPitchYawrateThrustConstPtr& msg) {
  double roll_cmd = msg->roll;
  double pitch_cmd = msg->pitch;
  double yaw_rate = msg->yaw_rate;
  double thrust = msg->thrust.z;

  dji_comm_.setRollPitchYawrateThrust(roll_cmd, pitch_cmd, yaw_rate, thrust);
}

} /* namespace dji_interface */

