class SmtpManager
{
public:
  struct Action
  {
    bool m_IsSendMessage = false;
    bool m_IsCreateMessage = false;
    bool m_IsSendCreatedMessage = false;
    std::string m_From;
    std::string m_To;
    std::string m_Cc;
    std::string m_Bcc;
    std::string m_Att;
    std::string m_Subject;
    std::string m_Body;
