						constexpr uint8_t buttonCount = 3;
						float buttonStartPositionX = maxRegion.x * 0.5f - buttonCount * 0.5f * buttonSize.x;

						ImGui::InvisibleButton("TitlebarGrab2", { buttonStartPositionX - ImGui::GetCursorPosX(), maxRegion.y });
