    // Hide the process dialogue (re-enables main window)
    analyseTestDataProgressDialog->hide();

    // Show an error
    QMessageBox messageBox;
    messageBox.critical(this, "Error","Test data failed integrity check!");
    messageBox.setFixedSize(500, 200);
}

