#New
int mean(std::vector< std::vector<int> > data, unsigned long v) {
  int sum = 0;
  int count = 0;
  for (unsigned long i = 0; i < data.size(); i++) {
    if (data[i][v] != -1) {
      sum += data[i][v];
      count++;
    }
  }
  return sum / count;
}

