    KOKKOS_INLINE_FUNCTION
    void operator() (TagAtomUnpackReverse, const int& i) const;

    KOKKOS_INLINE_FUNCTION
    int pack_border(int, MMD_float*, const int*) const;
    KOKKOS_INLINE_FUNCTION
    int unpack_border(int, MMD_float*) const;
    KOKKOS_INLINE_FUNCTION
