    if(neighbor.halfneigh && neighbor.ghost_newton)
      comm.reverse_communicate(atom);
    atom.v = atom.v + (0.5 * integrate.dt) * atom.f;
    if(i % thermo.nstat == 0) {
      thermo.compute(i, atom, neighbor, force, timer, comm);
