void Thermo::compute(int iflag, Atom &atom, Neighbor &neighbor, Force* force, Timer &timer, Comm &comm) {
  MMD_float t = 0;
  MMD_float e = 0;
  MMD_float p = 0;
  MMD_float virial = 0;
  if(iflag > 0) {
    t = temperature(atom, iflag);
    e = energy(atom, force);
    p = pressure(t, virial);
  }
  if(iflag < 0) {
    e = energy(atom, force);
    p = pressure(t, virial);
  }
  if(iflag == 0) {
    t = temperature(atom, iflag);
  }
  if(comm.me == 0) {
    if(iflag > 0) {
      printf("%i %e %e %e %e\n", iflag, t, e, p, timer.array[TIME_LOOP]);
    }
    if(iflag < 0) {
      printf("%i %e %e %e %e\n", iflag, t, e, p, timer.array[TIME_LOOP]);
    }
    if(iflag == 0) {
      printf("%i %e %e %e %e\n", iflag, t, e, p, timer.array[TIME_LOOP]);
    }
  }
}

