  asio::awaitable<void> process_connect(const InjecteeConnect &msg) override {
    if (auto v = msg["proxy"_f])
      info("{}: {} {} via {}", (int)pid_, *msg["syscall"_f], *msg["addr"_f],
           *v);
    else
      info("{}: {} {}", (int)pid_, *msg["syscall"_f], *msg["addr"_f]);
    co_return;
