  _assert_(key);
  std::map<std::string, std::string>::const_iterator it = map.find(key);
  if (it == map.end()) {
    if (sp) *sp = 0;
    return NULL;
  }
  if (sp) *sp = it->second.size();
  return it->second.c_str();
}


/**
