#ifndef NCMPCPP_SCREEN_TYPE_H
#define NCMPCPP_SCREEN_TYPE_H

#include <string>
#include "config.h"

// forward declaration
struct BaseScreen;

enum class ScreenType {
	Browser,
#	ifdef ENABLE_CLOCK
	Clock,
#	endif // ENABLE_CLOCK
	Help,
	Lastfm,
	Lyrics,
	MediaLibrary,
#	ifdef ENABLE_OUTPUTS
	Outputs,
#	endif // ENABLE_OUTPUTS
	Playlist,
	PlaylistEditor,
	SearchEngine,
	SelectedItemsAdder,
	ServerInfo,
	SongInfo,
	SortPlaylistDialog,
#	ifdef HAVE_TAGLIB_H
	TagEditor,
	TinyTagEditor,
#	endif // HAVE_TAGLIB_H
	Unknown,
#	ifdef ENABLE_VISUALIZER
	Visualizer,
#	endif // ENABLE_VISUALIZER
};

