    template<int EVFLAG, int STACK_PARAMS>
    KOKKOS_INLINE_FUNCTION
    void operator() (TagComputeFullNeigh<EVFLAG,STACK_PARAMS> , const int& i, eng_virial_type& eng_virial ) const;

};

