  MMD_float t = 0;
  MMD_float e = 0;
  MMD_float p = 0;
  MMD_float virial = 0;
  if(iflag > 0) {
    t = temperature(atom, iflag);
    e = energy(atom, force);
    p = pressure(t, virial);
  }
  if(iflag < 0) {
    e = energy(atom, force);
    p = pressure(t, virial);
