  }

  row_exp_sum = aShared[0];

  // Remember, we've already set the appropriate matrix elements to 0.
  for (var i : u32 = 0; i < kColsPerThread; i = i + 1) {
    if (!isOutOfBounds(M,N, indexX + i, indexY))
    {
