  let outputIndexA = vec2<u32>(
    workGroupID.xy * vec2<u32>(kWorkgroupX, kWorkgroupY) +
    localInvocationId.xy);

  if (!isOutOfBounds(M, N, outputIndexA.x, outputIndexA.y)) {
