#include "apefile.h"
#include "apetag.h"
#include "id3v1tag.h"
#include "id3v2tag.h"
#include "apefooter.h"
#include "apeproperties.h"
#include "tstring.h"
#include "tpropertymap.h"
#include "tdebug.h"

using namespace TagLib;
using namespace APE;

class File::FilePrivate
{
public:
  FilePrivate() : properties(0), APELocation(-1), APESize(0), ID3v1Tag(0), APEtag(0) {}
  ~FilePrivate() {
    delete properties;
    delete ID3v1Tag;
    delete APEtag;
  }

  Properties *properties;
  long APELocation;
  unsigned int APESize;
  ID3v1::Tag *ID3v1Tag;
  APE::Tag *APEtag;
};

File::File(FileName file, bool readProperties, Properties::ReadStyle propertiesStyle)
  : TagLib::File(file)
{
  d = new FilePrivate;
  if(isOpen()) {
    read(readProperties, propertiesStyle);
  }
}

File::File(IOStream *stream, bool readProperties, Properties::ReadStyle propertiesStyle)
  : TagLib::File(stream)
{
  d = new FilePrivate;
  if(isOpen()) {
    read(readProperties, propertiesStyle);
  }
}

File::~File()
{
  delete d;
}

Tag *File::tag() const
{
  return APEtag();
}

PropertyMap File::properties() const
{
  return APEtag()->properties();
}

void File::removeUnsupportedProperties(const StringList &properties)
{
  APEtag()->removeUnsupportedProperties(properties);
}

PropertyMap File::setProperties(const PropertyMap &properties)
{
  return APEtag()->setProperties(properties);
}

Properties *File::audioProperties() const
{
  return d->properties;
}

bool File::save()
{
  if(readOnly()) {
    debug("File::save() -- File is read only.");
    return false;
  }

  // Update ID3v1 tag with APE tag contents
  if(ID3v1Tag()) {
    setID3v1Tag(ID3v1Tag());
  }

  return true;
}

ID3v1::Tag *File::ID3v1Tag(bool create)
{
  if(!create || d->ID3v1Tag) {
    return d->ID3v1Tag;
  }

  d->ID3v1Tag = new ID3v1::Tag();
  return d->ID3v1Tag;
}

APE::Tag *File::APETag(bool create)
{
  if(!create || d->APEtag) {
    return d->APEtag;
  }

  d->APEtag = new APE::Tag();
  return d->APEtag;
}

void File::strip(int tags)
{
  if(tags & ID3v1) {
    delete d->ID3v1Tag;
    d->ID3v1Tag = 0;
  }

  if(tags & APE) {
    delete d->APEtag;
    d->APEtag = 0;
  }
}

bool File::hasAPETag() const
{
  return d->APEtag != 0;
}

bool File::hasID3v1Tag() const
{
  return d->ID3v1Tag != 0;
}

bool File::isSupported(IOStream *stream)
{
  // APE tag is always at the end of the file
  stream->seek(-32, IOStream::End);
  return stream->readBlock(3).startsWith("APETAGEX");
}

void File::read(bool readProperties, Properties::ReadStyle propertiesStyle)
{
  // Look for an ID3v1 tag
  seek(-128, End);
  if(readBlock(3) == "TAG") {
    d->ID3v1Tag = new ID3v1::Tag(this, 0);
    seek(-128, End);
  }

  // Look for an APE tag
  seek(-32, End);
  if(readBlock(8) == "APETAGEX") {
    d->APELocation = tell() - 32;
    seek(8, Current);
    d->APESize = readBlock(4).toUInt(0, false);
    d->APEtag = new APE::Tag(this, d->APELocation);
  }

  if(readProperties) {
    d->properties = new Properties(this, d->APELocation, propertiesStyle);
  }
}

// New: Add a method to get the total number of items in the APE tag
unsigned int File::totalItemsInAPETag() const
{
  if(d->properties) {
    return d->properties->totalItems();
  }
  return 0;
}

