      _calculatedChecksum += ch;
      break;

    default:
      if (_index == _frameLen + 2)
      {
        _checksum = ch << 8;
      }
      else if (_index == _frameLen + 2 + 1)
      {
        _checksum |= ch;

        if (_calculatedChecksum == _checksum)
        {
          _status = STATUS_OK;

          // Standard Particles, CF=1.
          _data->PM_SP_UG_1_0 = makeWord(_payload[0], _payload[1]);
          _data->PM_SP_UG_2_5 = makeWord(_payload[2], _payload[3]);
          _data->PM_SP_UG_10_0 = makeWord(_payload[4], _payload[5]);

          // Atmospheric Environment.
          _data->PM_AE_UG_1_0 = makeWord(_payload[6], _payload[7]);
          _data->PM_AE_UG_2_5 = makeWord(_payload[8], _payload[9]);
          _data->PM_AE_UG_10_0 = makeWord(_payload[10], _payload[11]);
        }

        _index = 0;
        return;
      }
      else
      {
        _calculatedChecksum += ch;
        uint8_t payloadIndex = _index - 4;

        // Payload is common to all sensors (first 2x6 bytes).
        if (payloadIndex < sizeof(_payload))
        {
          _payload[payloadIndex] = ch;
        }
      }

      break;
    }

    _index++;
  }
}

void PMS::logData(const DATA& data) // New
{
  if (!SD.begin(BUILTIN_SDCARD)) {
    return;
  }
  logFile = SD.open("log.txt", FILE_WRITE);
  if (logFile) {
    logFile.print("PM_SP_UG_1_0:");
    logFile.print(data.PM_SP_UG_1_0);
    logFile.print(", PM_SP_UG_2_5:");
    logFile.print(data.PM_SP_UG_2_5);
    logFile.print(", PM_SP_UG_10_0:");
    logFile.print(data.PM_SP_UG_10_0);
    logFile.print(", PM_AE_UG_1_0:");
    logFile.print(data.PM_AE_UG_1_0);
    logFile.print(", PM_AE_UG_2_5:");
    logFile.print(data.PM_AE_UG_2_5);
    logFile.print(", PM_AE_UG_10_0:");
    logFile.println(data.PM_AE_UG_10_0);
    logFile.close();
  }
}

