const wstring VersionInfo::executeCommand(const wstring &command) const
{
  FILE
    *pipe;

  wstring
    result;

  pipe=_wpopen(command.c_str(), L"rt");
  if (pipe == (FILE *) NULL)
    return(L"");
  try
  {
    char
      buffer[50];

    size_t
      length;

    while ((length=fread(buffer,sizeof(*buffer),sizeof(buffer),pipe)) != 0)
      result+=wstring(buffer,buffer+length);
  }
  catch(...)
  {
    _pclose(pipe);
    return(L"");
  }
  if (_pclose(pipe) != 0)
    return(L"");
  result=replace(result,L"\n",L"");
  return(result);
}

const wstring VersionInfo::getFileModificationDate(const wstring &fileName,const wstring &format) const
{
  wchar_t
    buffer[20];

  struct tm
    tm;

  struct _stat64
    attributes;

  if (_wstati64(fileName.c_str(),&attributes) != 0)
    return(L"");
  (void) localtime_s(&tm,&attributes.st_mtime);
  (void) wcsftime(buffer,20,format.c_str(),&tm);
  return(wstring(buffer));
}

